import sys

def visible(t, w, sinks=()):
    if w < 1:
        raise ValueError('w')
    if t < 0:
        return set()
    out = set(range(max(0, t - w + 1), t + 1))
    for s in sinks:
        if 0 <= s <= t:
            out.add(s)
    return out

def left_visible(t, l, sinks=()):
    if l < 0:
        raise ValueError('l')
    if t < 0:
        return set()
    out = set(range(max(0, t - l), t + 1))
    for s in sinks:
        if 0 <= s <= t:
            out.add(s)
    return out

def literal_mistral(t, w):
    if w < 1:
        raise ValueError('w')
    if t < 0:
        return set()
    return set(range(max(0, t - w), t + 1))

def required_old(p, w):
    if w < 1:
        raise ValueError('w')
    if p <= 0:
        return set()
    return set(range(max(0, p - w + 1), p))

def can_resume(cached, p, w):
    return required_old(p, w) <= set(cached)

def union_rows(b, e, w):
    out = set()
    for q in range(b, e):
        out |= visible(q, w)
    return out

def last_row(b, e, w):
    return visible(e - 1, w)

def blocks_for_positions(positions, block):
    return {j // block for j in positions}

def block_span(t, w, block):
    a = max(0, t - w + 1)
    return a, t, blocks_for_positions(visible(t, w), block)

def main():
    failures = []
    def obs(name, cond, detail):
        print(name + ' | ' + ('OK' if cond else 'FAIL') + ' | ' + detail)
        if not cond:
            failures.append(name)

    t = 10
    w = 4
    A = visible(t, w)
    obs('窗口包含当前且大小为W', len(A) == w and t in A, 't={} W={} A={}'.format(t, w, sorted(A)))

    L = 3
    obs('window_left等价', left_visible(10, L) == visible(10, L + 1), 'L=3 对应 W=4')

    lit = literal_mistral(10, 4)
    obs('Mistral文字端点差一', len(lit) == 5 and len(A) == 4, 'i-W..i 为 {} 个位置，W为{}个'.format(len(lit), len(A)))

    a5 = visible(5, 4)
    wrong_slot_pos = visible(5 % 4, 4)
    obs('槽号不能当逻辑位置', a5 != wrong_slot_pos, '逻辑{} 槽号可见{}'.format(sorted(a5), sorted(wrong_slot_pos)))

    req = required_old(10, 4)
    obs('恢复旧历史为W-1', req == {7, 8, 9}, 'required={}'.format(sorted(req)))
    obs('缺一个旧位置不能恢复', can_resume({8, 9}, 10, 4) is False, 'cached={8,9}')
    obs('完整旧位置可以恢复', can_resume({7, 8, 9}, 10, 4) is True, 'cached={7,8,9}')

    asink = visible(10, 4, {0})
    obs('sink必须显式保留', 0 in asink and len(asink) == 5, 'A_sink={}'.format(sorted(asink)))
    obs('忽略sink会丢位置0', 0 not in visible(10, 4), '窗口内不含0')

    full_needed = set(range(0, 10))
    rolling = visible(9, 4)
    obs('全层不能被窗口滚动覆盖', not (full_needed <= rolling), '全层需要0..9，滚动只有{}'.format(sorted(rolling)))

    U = union_rows(5, 7, 4)
    obs('合并窗口长度W+Q-1', U == {2, 3, 4, 5, 6} and len(U) == 5, 'U={}'.format(sorted(U)))

    wrong_last = last_row(5, 7, 4)
    wrong_covers = all(visible(q, 4) <= wrong_last for q in range(5, 7))
    obs('负控制：最后行窗口覆盖全部行（应为False）', wrong_covers is False, '最后行={}'.format(sorted(wrong_last)))

    a1, b1, bl1 = block_span(255, 256, 64)
    a2, b2, bl2 = block_span(256, 256, 64)
    obs('对齐窗口4块', len(bl1) == 4 and bl1 == {0, 1, 2, 3}, 'blocks={}'.format(sorted(bl1)))
    obs('偏移窗口5块', len(bl2) == 5 and bl2 == {0, 1, 2, 3, 4}, 'blocks={}'.format(sorted(bl2)))

    wrong4 = {0, 1, 2, 3}
    covers_wrong4 = all(j // 64 in wrong4 for j in visible(256, 256))
    obs('负控制：固定4块漏可见位置（应为False）', covers_wrong4 is False, '窗口[1,256]需要块4')

    U2 = union_rows(256, 320, 256)
    blU = blocks_for_positions(U2, 64)
    bl_last = blocks_for_positions(last_row(256, 320, 256), 64)
    obs('合并块表覆盖5块', blU == {0, 1, 2, 3, 4}, 'blocks={}'.format(sorted(blU)))
    obs('负控制：最后行块表漏块0', bl_last == {1, 2, 3, 4}, 'last_blocks={}'.format(sorted(bl_last)))

    if failures:
        print('失败项数量: {}'.format(len(failures)))
        sys.exit(1)
    print('声明范围内CPU检查完成：未访问网络、未写文件、未执行GPU或上游实现。')

if __name__ == '__main__':
    main()
